# ---------- 写盘与校验 ----------
assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
assert len(P) == 27
os.makedirs(BASE, exist_ok=True)
total = 0
for cid in IDS:
    d = P[cid]
    out = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["conf"], "trigger": d["trig"]}
    assert set(out.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(out["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
    total += os.path.getsize(path)
cm = sum(1 for c in IDS if P[c]["trig"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trig"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trig"]["disputed"])
print("WROTE", len(IDS), "TOTALBYTES", total, "TRIGGER changed_main", cm, "reserve_used", ru, "disputed", di)
